let MAP = 1;
const SOLIDS = [], SPIKES = [], STAR_POS = [], ENEMY_DEF = [], FLOWERS = [], SIGNS = [], CHECKPOINTS = [], TIPS = [], FLYER_DEF = [], GROUNDS = [], HEARTS = [];
