  ctx.fillStyle = SK2; ctx.fillRect(-2, -82, 4, 34);
  ctx.strokeStyle = GL; ctx.lineWidth = 1.6; ctx.globalAlpha *= .9;
  ctx.beginPath();
  ctx.moveTo(-9, -78); ctx.lineTo(-3, -70); ctx.lineTo(-8, -60); ctx.moveTo(9, -78); ctx.lineTo(3, -70); ctx.lineTo(8, -60);
