  al2: 'data:image/png;base64,',
  sh: 'data:image/png;base64,',
  orb0: 'data:image/png;base64,',
  orb: 'data:image/png;base64,',
  lz0: 'data:image/png;base64,',
  lz1: 'data:image/png;base64,',
