  stand: [['ah', -25, -56], ['al', -13, -16], ['ab', -19, -35]],
  roar:  [['ah2', -20, -54], ['al', -13, -16], ['ab', -19, -35]],
  dash:  [['ah2', -20, -54], ['al2', -36, -20], ['ab2', -41, -34]],
