  ctx.fillStyle = '#5a4030'; ctx.fillRect(-7.5, -21, 15, 3);
  ctx.fillStyle = ROBE;
  ctx.beginPath(); ctx.moveTo(-8, -36); ctx.lineTo(4, -36); ctx.lineTo(-2, -29); ctx.lineTo(-8, -28); ctx.closePath(); ctx.fill();
